pub fn ingest(station: &str, value: i32) -> Result<(String, i32), &'static str> {
    if station.is_empty() { return Err("no station id"); }
    Ok((station.to_string(), value))
}

use std::collections::HashSet;
pub fn store(seen: &mut HashSet<(String, i64)>, station: &str, ts: i64, _v: i32) -> bool {
    seen.insert((station.to_string(), ts))
}
